# Global variables
filename = ""
selected_scanner = None
scanner_list = []

# Constants
A4_WIDTH_MM = 210
A4_HEIGHT_MM = 297
DPI = 300  # Standard DPI for scanning
MOVE_UP_PIXELS = 38  # Move the logo and widgets up by approximately 38 pixels
DISPLAY_WIDTH = 400  # Width to resize the displayed image
DISPLAY_HEIGHT = 300  # Height to resize the displayed image

# Base64 encoded string of the image
LOGO_BASE64 = '''

'''

def get_logo_image():
    logo_data = base64.b64decode(LOGO_BASE64)
    image = Image.open(io.BytesIO(logo_data))
    return image

# Functions
def browse_file():
    global filename
    filename = filedialog.askopenfilename(filetypes=[("Image files", "*.png;*.jpg;*.jpeg;*.bmp;*.tiff")])
    if filename:
        entry.delete(0, tk.END)
        entry.insert(0, shorten_path(filename))

def shorten_path(path, length=40):
    if len(path) <= length:
        return path
    else:
        parts = path.replace("\\", "/").split("/")
        return os.path.join("...", *parts[-2:])

def calculate_percentage_above_threshold(image):
    height, width, _ = image.shape
    num_pixels_original = height * width
    hsv_image = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
    _, _, v = cv2.split(hsv_image)
    _, value_mask = cv2.threshold(v, 223, 255, cv2.THRESH_BINARY_INV)
    num_pixels_above_threshold = cv2.countNonZero(value_mask)
    return (num_pixels_above_threshold / num_pixels_original) * 100

def calculate_area_below_threshold(image):
    height, width, _ = image.shape
    hsv_image = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
    _, _, v = cv2.split(hsv_image)
    _, value_mask = cv2.threshold(v, 223, 255, cv2.THRESH_BINARY_INV)
    num_pixels_below_threshold = cv2.countNonZero(value_mask)
    
    # Convert pixels to square millimeters
    mm_per_pixel = (25.4 / DPI)  # 1 inch = 25.4 mm
    area_per_pixel_mm2 = mm_per_pixel ** 2
    area_below_threshold_mm2 = num_pixels_below_threshold * area_per_pixel_mm2
    
    return area_below_threshold_mm2

def calculate_percentage_above_threshold_read(image):
    height, width, _ = image.shape
    num_pixels_original = height * width
    hsv_image = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
    _, _, v = cv2.split(hsv_image)
    _, value_mask = cv2.threshold(v, 250, 255, cv2.THRESH_BINARY)
    num_pixels_above_threshold = cv2.countNonZero(value_mask)
    return (num_pixels_above_threshold / num_pixels_original) * 100

def calculate_area_below_threshold_read(image):
    height, width, _ = image.shape
    hsv_image = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
    _, _, v = cv2.split(hsv_image)
    _, value_mask = cv2.threshold(v, 250, 255, cv2.THRESH_BINARY)
    num_pixels_below_threshold = cv2.countNonZero(value_mask)
    
    # Convert pixels to square millimeters
    mm_per_pixel = (25.4 / DPI)  # 1 inch = 25.4 mm
    area_per_pixel_mm2 = mm_per_pixel ** 2
    area_below_threshold_mm2 = num_pixels_below_threshold * area_per_pixel_mm2
    
    return area_below_threshold_mm2

def read_file():
    global filename
    if filename:
        try:
            original_image = cv2.imread(filename)
            process_image_read(original_image)
        except Exception as e:
            messagebox.showerror("Error", f"An error occurred: {e}")
    else:
        messagebox.showerror("Error", "Please select a file first")

def process_image(image):
    # Convert the image to grayscale
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    
    # Apply Gaussian blur to remove noise
    blurred = cv2.GaussianBlur(gray, (3, 3), 0)
    
    # Apply adaptive thresholding to obtain a binary image
    thresh = cv2.adaptiveThreshold(blurred, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY_INV, 11, 3)
    
    # Perform morphological operations to close gaps and smooth edges
    kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (10, 10))
    closed = cv2.morphologyEx(thresh, cv2.MORPH_CLOSE, kernel)
    
    # Find contours in the binary image including hierarchy
    contours, hierarchy = cv2.findContours(closed.copy(), cv2.RETR_CCOMP, cv2.CHAIN_APPROX_SIMPLE)
    
    # Iterate through the contours and hierarchy
    total_area = 0
    for i, contour in enumerate(contours):
        # Check if contour has parent (exterior contour)
        if hierarchy[0][i][3] == -1:
            # Fill the contour (element) with white color
            cv2.drawContours(closed, [contour], 0, (255, 255, 255), -1)
            
            # Calculate area of the filled contour
            area = cv2.contourArea(contour)
            if area > 100:  # Ignore small noise
                total_area += area
    
    # Calculate percentage of total area in the image
    height, width = image.shape[:2]
    total_image_area = height * width
    percentage_area = (total_area / total_image_area) * 100
    
    # Update labels with results
    percentage_label.config(text=f"Percentage of Area within Elements: {percentage_area:.2f}%")
    area_label.config(text=f"Area within Elements: {((62370 / 100) * percentage_area):.2f} mm2")

    # Ensure the interactive backend is used
    #plt.switch_backend('TkAgg')

    # Resize the processed image and the original image for display
    DISPLAY_WIDTH, DISPLAY_HEIGHT = 800, 600  # Set the desired display size
    scaled_closed = cv2.resize(closed, (DISPLAY_WIDTH, DISPLAY_HEIGHT))
    scaled_original = cv2.resize(image, (DISPLAY_WIDTH, DISPLAY_HEIGHT))

    # Convert the original image from BGR to RGB for displaying with matplotlib
    scaled_original_rgb = cv2.cvtColor(scaled_original, cv2.COLOR_BGR2RGB)

    # Display the images using matplotlib
    fig, axs = plt.subplots(1, 2, figsize=(16, 8))

    # Display the original image
    axs[0].imshow(scaled_original_rgb)
    axs[0].set_title("Original Image")
    axs[0].axis('off')

    # Display the processed image
    axs[1].imshow(scaled_closed, cmap='gray')
    axs[1].set_title("Processed Image")
    axs[1].axis('off')

    plt.show()
    
    # Resize the processed image and the original image for display
    #DISPLAY_WIDTH, DISPLAY_HEIGHT = 800, 600  # Set the desired display size
    #scaled_closed = cv2.resize(closed, (DISPLAY_WIDTH, DISPLAY_HEIGHT))
    #scaled_original = cv2.resize(image, (DISPLAY_WIDTH, DISPLAY_HEIGHT))
    
    # Display the original image in a separate window
    #cv2.imshow("Original Image", scaled_original)
    
    # Display the processed image in another window
    #cv2.imshow("Processed Image", scaled_closed)
    
    # Keep the windows always on top
    #cv2.setWindowProperty("Original Image", cv2.WND_PROP_TOPMOST, 1)
    #cv2.setWindowProperty("Processed Image", cv2.WND_PROP_TOPMOST, 1)
    
    # Wait for a key press to close the windows
    cv2.waitKey(0)
    cv2.destroyAllWindows()






def process_image_read(image):
    # Convert the image to grayscale
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    
    # Apply Gaussian blur to remove noise
    blurred = cv2.GaussianBlur(gray, (3, 3), 0)
    
    # Apply adaptive thresholding to obtain a binary image
    thresh = cv2.adaptiveThreshold(blurred, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY_INV, 11, 2)
    
    # Perform morphological operations to close gaps and smooth edges
    kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (10, 10))
    closed = cv2.morphologyEx(thresh, cv2.MORPH_CLOSE, kernel)
    
    # Find contours in the binary image including hierarchy
    contours, hierarchy = cv2.findContours(closed.copy(), cv2.RETR_CCOMP, cv2.CHAIN_APPROX_SIMPLE)
    
    # Iterate through the contours and hierarchy
    total_area = 0
    for i, contour in enumerate(contours):
        # Check if contour has parent (exterior contour)
        if hierarchy[0][i][3] == -1:
            # Fill the contour (element) with white color
            cv2.drawContours(closed, [contour], 0, (255, 255, 255), -1)
            
            # Calculate area of the filled contour
            area = cv2.contourArea(contour)
            if area > 100:  # Ignore small noise
                total_area += area
    
    # Calculate percentage of total area in the image
    height, width = image.shape[:2]
    total_image_area = height * width
    percentage_area = (total_area / total_image_area) * 100
    


    # Update labels with results
    percentage_label.config(text=f"Percentage of Area within Elements: {percentage_area:.2f}%")
    area_label.config(text=f"Area within Elements: {((62370/100)*percentage_area):.2f}mm2")
    
     # Resize the processed image and the original image for display
    DISPLAY_WIDTH, DISPLAY_HEIGHT = 800, 600  # Set the desired display size
    scaled_closed = cv2.resize(closed, (DISPLAY_WIDTH, DISPLAY_HEIGHT))
    scaled_original = cv2.resize(image, (DISPLAY_WIDTH, DISPLAY_HEIGHT))

    # Convert the original image from BGR to RGB for displaying with matplotlib
    scaled_original_rgb = cv2.cvtColor(scaled_original, cv2.COLOR_BGR2RGB)

    # Display the images using matplotlib
    fig, axs = plt.subplots(1, 2, figsize=(16, 8))

    # Display the original image
    axs[0].imshow(scaled_original_rgb)
    axs[0].set_title("Original Image")
    axs[0].axis('off')

    # Display the processed image
    axs[1].imshow(scaled_closed, cmap='gray')
    axs[1].set_title("Processed Image")
    axs[1].axis('off')

    plt.show()
    
    # Wait for a key press to close the windows
    cv2.waitKey(0)
    cv2.destroyAllWindows()


def show_value_image(value_image, title):
    # Resize the value channel image to fit the display dimensions
    value_image_resized = cv2.resize(value_image, (DISPLAY_WIDTH, DISPLAY_HEIGHT))
    image_pil = Image.fromarray(value_image_resized)
    window = tk.Toplevel(root)
    window.title(title)
    photo = ImageTk.PhotoImage(image_pil)
    label = tk.Label(window, image=photo)
    label.image = photo
    label.pack()
    
    # Add a label to show the pixel values
    pixel_value_label = tk.Label(window, text="Pixel Value: ")
    pixel_value_label.pack()

    def motion(event):
        x, y = event.x, event.y
        if 0 <= x < DISPLAY_WIDTH and 0 <= y < DISPLAY_HEIGHT:
            pixel_value = value_image_resized[y, x]
            pixel_value_label.config(text=f"Pixel Value: {pixel_value}")

    # Bind the motion event to the label
    label.bind('<Motion>', motion)

def scan_image():
    global selected_scanner
    if not selected_scanner:
        messagebox.showerror("Error", "Please select a scanner first")
        return
    
    try:
        wia = win32com.client.Dispatch("WIA.CommonDialog")
        device_manager = win32com.client.Dispatch("WIA.DeviceManager")
        device = None

        for info in device_manager.DeviceInfos:
            if info.DeviceID == selected_scanner:
                device = info.Connect()
                break

        if not device:
            messagebox.showerror("Error", "Scanner not found")
            return

        item = device.Items[1]
        img_w, img_h = int(A4_WIDTH_MM / 25.4 * DPI), int(A4_HEIGHT_MM / 25.4 * DPI)

        # Set properties
        item.Properties["Horizontal Resolution"].Value = DPI
        item.Properties["Vertical Resolution"].Value = DPI
        item.Properties["Horizontal Extent"].Value = img_w
        item.Properties["Vertical Extent"].Value = img_h

        # Transfer the image in BMP format
        image = wia.ShowTransfer(item, "{B96B3CAB-0728-11D3-9D7B-0000F81EF32E}")  # wiaFormatBMP

        if image:
            tmpfile_name = os.path.join(tempfile.gettempdir(), f"{uuid.uuid4()}.bmp")
            if os.path.exists(tmpfile_name):
                os.remove(tmpfile_name)
            image.SaveFile(tmpfile_name)
            global filename
            filename = tmpfile_name
            original_image = cv2.imread(filename)
            process_image(original_image)

    except Exception as e:
        messagebox.showerror("Error", f"An error occurred while scanning: {e}")

def update_scanner_list():
    try:
        device_manager = win32com.client.Dispatch("WIA.DeviceManager")
        global scanner_list
        scanner_list = [device.DeviceID for device in device_manager.DeviceInfos if device.Type == 1]
        if not scanner_list:
            messagebox.showerror("Error", "No scanner devices found")
            return

        scanner_var.set(scanner_list[0])
        scanner_menu['menu'].delete(0, 'end')
        for scanner in scanner_list:
            scanner_menu['menu'].add_command(label=scanner, command=tk._setit(scanner_var, scanner))

    except Exception as e:
        messagebox.showerror("Error", f"An error occurred while updating scanner list: {e}")

def on_scanner_select(*args):
    global selected_scanner
    selected_scanner = scanner_var.get()

def exit_app():
    root.destroy()

# Main window
root = tk.Tk()
root.title("File Input")

# Set window to full size
root.state('zoomed')  # For Windows

# For cross-platform, use:
# root.geometry("{0}x{1}+0+0".format(root.winfo_screenwidth(), root.winfo_screenheight()))

# Load background image and resize it
try:
    bg_image = get_logo_image()
    bg_width, bg_height = bg_image.size
    new_size = (int(bg_width * 0.9), int(bg_height * 0.9))  # Decrease size by 10%
    bg_image = bg_image.resize(new_size, Image.LANCZOS)
    bg_photo = ImageTk.PhotoImage(bg_image)
    bg_label = tk.Label(root, image=bg_photo)
    bg_label.place(x=0, y=-MOVE_UP_PIXELS, relwidth=1, relheight=1)  # Move logo up by 38 pixels
except Exception as e:
    messagebox.showerror("Error", f"Error loading background image: {e}")

# Create a frame to hold widgets
frame = tk.Frame(root, bg='white')
frame.place(relx=0.5, rely=0.95 - (MOVE_UP_PIXELS / root.winfo_screenheight()), anchor='center')  # Move frame up

# Create and position widgets
label = tk.Label(frame, text="Enter file path:", bg='white')
label.grid(row=2, column=0, pady=5)

entry = tk.Entry(frame, width=50)
entry.grid(row=2, column=1, columnspan=4, pady=5)

browse_button = tk.Button(frame, text="Browse", command=browse_file)
browse_button.grid(row=2, column=5, padx=5, pady=5)

scanner_label = tk.Label(frame, text="Select Scanner:", bg='white')
scanner_label.grid(row=3, column=0, pady=5)

scanner_var = tk.StringVar(frame)
scanner_var.trace("w", on_scanner_select)
scanner_menu = tk.OptionMenu(frame, scanner_var, "")
scanner_menu.grid(row=3, column=1, columnspan=4, pady=5)

update_scanner_button = tk.Button(frame, text="Update Scanner List", command=update_scanner_list)
update_scanner_button.grid(row=3, column=5, padx=5, pady=5)

scan_button = tk.Button(frame, text="Read File", command=read_file)
scan_button.grid(row=2, column=6, padx=5, pady=5)

read_button = tk.Button(frame, text="Scan", command=scan_image)
read_button.grid(row=2, column=7, padx=5, pady=5)

exit_button = tk.Button(frame, text="Exit", command=exit_app)
exit_button.grid(row=2, column=8, padx=5, pady=5)

# Labels for displaying results
percentage_label = tk.Label(frame, text="", bg='white')
percentage_label.grid(row=4, column=0, columnspan=4, pady=5)

area_label = tk.Label(frame, text="", bg='white')
area_label.grid(row=4, column=4, columnspan=4, pady=5)

# Initialize scanner list
update_scanner_list()

# Start the main event loop
root.mainloop()
